-- Complete the remaining 127 country/territory Market Access evidence rows.
-- Research basis: 2026 CannabisRegulations.ai country index, which states that
-- each jurisdiction is traced to primary law and reviewed/dated; primary-source
-- spot checks were also performed for high-impact exceptions.
-- This migration does NOT reuse countries.regulatory_tier as evidence.
--
-- Verified at: 2026-09-13. Evidence review expiry: 2027-03-13.

on conflict (evidence_key) do update set
  jurisdiction_iso2=excluded.jurisdiction_iso2,
  tier=excluded.tier,
  rationale=excluded.rationale,
  authority_name=excluded.authority_name,
  authority_url=excluded.authority_url,
  source_effective_date=excluded.source_effective_date,
  verified_at=excluded.verified_at,
  expires_at=excluded.expires_at,
  active=true;

select * from api.refresh_verified_market_access_tiers('market-access-complete-127-20260913');

do $$
declare
  v_total integer;
  v_published integer;
  v_missing integer;
  v_gap integer;
begin
  select count(*) into v_total from public.countries where iso_alpha2 is not null;
  select count(*) into v_published from public.countries
   where iso_alpha2 is not null and verified_regulatory_tier is not null;
  select count(*) into v_missing from public.countries
   where iso_alpha2 is not null and verified_regulatory_tier is null;
  select count(*) into v_gap from public.countries c
   where c.iso_alpha2 in ('PR','AE','GD','BA','LC','EE','LA','BE','BJ','NA','BT','GE','LB','PK','MY','FJ','GM','BS','AG','SV','FK','CV','CD','AM','FO','SZ','LI','SM','AO','EG','BO','CU','KH','ET','BZ','BN','ID','KM','PH','VN','AD','BF','BI','CM','CI','DJ','LR','DM','DO','NI','BH','NP','RO','DZ','CF','TD','GQ','ER','GA','GN','GW','LY','MG','ML','MR','MU','MZ','NE','CG','ST','SN','SC','SL','SO','SS','SD','TG','TN','UG','EH','GL','GT','HT','HN','SR','VE','AF','AZ','BD','HK','IR','IQ','JO','KZ','KW','KG','MV','MN','MM','KP','OM','PS','QA','SA','SY','TW','TJ','TL','TM','UZ','YE','VA','IS','XK','LV','MC','ME','KI','MH','FM','NR','PW','PG','WS','SB','TO','TV')
     and c.verified_regulatory_tier is null;

  if v_total <> 291 then raise exception 'Expected 291 jurisdiction rows, found %', v_total; end if;
  if v_gap <> 0 then raise exception 'Expected zero unpublished rows in completed 127 gap, found %', v_gap; end if;
  if v_missing <> 0 then raise exception 'Expected zero unpublished rows after complete evidence refresh, found %', v_missing; end if;
  if v_published <> 291 then raise exception 'Expected 291 published verified tiers, found %', v_published; end if;
end $$;
